function handleSetTop(){let n=$("#overview-table-header").height();$("#overview-table-total > th").css({top:`${SUB_MENU_HEIGHT+n}px`})}function handleScroll(){if(window.innerWidth<SUPPORT_MIN_WITDH)$("#details-section-menu").removeClass("details-section-sticky");else{let n=$("#details-section").offset().top;window.pageYOffset>=n?$("#details-section-menu").addClass("details-section-sticky"):$("#details-section-menu").removeClass("details-section-sticky")}}function handleResize(){handleScroll();handleSetTop()}var SUPPORT_MIN_WITDH=716,SUB_MENU_HEIGHT=43;window.onscroll=handleScroll;window.addEventListener("resize",handleResize);$(document).ready(handleSetTop);